257	describe('FsArtifactStore', () => {
258	  // POSIX permits replacement while the destination is open; this exercises Windows sharing.
259	  it.skipIf(process.platform !== 'win32')(
260	    'accepts verified bytes published by another writer while a read handle blocks replacement',
261	    async () => {
262	      const content = 'x'.repeat(32 * 1024 * 1024);
263	      const bytes = Buffer.from(content);
264	      const hash = createHash('sha256').update(bytes).digest('hex');
265	      const ref = `artifact:transcript/${hash}`;
266	      const dir = join(dataDir, 'artifacts', 'transcript');
267	      const final = join(dir, hash);
268	      mkdirSync(dir, { recursive: true });
269	      let readHandle: number | undefined;
270	      let injected = false;
271	      let setupError: unknown;
272	      const observer = watch(dir, (_event, name) => {
273	        if (injected || !name?.startsWith(`.${hash}.`) || !name.endsWith('.tmp')) return;
274	        injected = true;
275	        try {
276	          // A .tmp proves put already checked the missing destination. Synchronous setup keeps
277	          // this callback ahead of put's remaining asynchronous write/fsync/rename continuations.
278	          statSync(join(dir, name));
279	          writeFileSync(final, bytes);
280	          readHandle = openSync(final, 'r');
281	        } catch (error) {
282	          setupError = error;
283	        }
284	      });
285	      const store = new FsArtifactStore(dataDir);
286	      try {
287	        await expect(store.put('transcript', content)).resolves.toEqual({
288	          ref,
289	          bytes: bytes.length,
290	        });
291	        expect(injected).toBe(true);
292	        expect(setupError).toBeUndefined();
293	        expect(readHandle).toBeDefined();
294	        expect(await store.get(ref)).toBe(content);
295	        expect(readFileSync(final).equals(bytes)).toBe(true);
296	        expect(readdirSync(dir)).toEqual([hash]);
297	      } finally {
298	        observer.close();
299	        if (readHandle !== undefined) closeSync(readHandle);
300	      }
301	    },
302	  );
303	
304	  it('rejects corrupted final bytes and atomically repairs a pre-existing partial file', async () => {
305	    const store = new FsArtifactStore(dataDir);
306	    const content = 'complete transcript: 世界 🧙';
307	    const hash = createHash('sha256').update(content).digest('hex');
308	    const dir = join(dataDir, 'artifacts', 'transcript');
309	    mkdirSync(dir, { recursive: true });
310	    writeFileSync(join(dir, hash), 'complete');
311	    const ref = `artifact:transcript/${hash}`;
312	    await expect(store.get(ref)).rejects.toMatchObject({ code: 'ARTIFACT_CORRUPT', ref });
313	    const repaired = await store.put('transcript', content);
314	    expect(repaired.ref).toBe(ref);
315	    expect(readFileSync(join(dir, hash)).equals(Buffer.from(content))).toBe(true);
316	    expect(await store.get(ref)).toBe(content);
317	    expect(readdirSync(dir)).toEqual([hash]);
318	  });
319	
