321	    const store = new FsArtifactStore(dataDir);
322	    const { ref } = await store.put('transcript', 'a complete transcript');
323	    const hash = ref.split('/')[1]!;
324	    writeFileSync(join(dataDir, 'artifacts', 'transcript', hash), 'a');
325	    expect(await store.put('transcript', 'a complete transcript')).toMatchObject({ ref });
326	    expect(await store.get(ref)).toBe('a complete transcript');
