329	  it('ignores interrupted temporary writes and converges under identical and different concurrent puts', async () => {
330	    const store = new FsArtifactStore(dataDir);
331	    const dir = join(dataDir, 'artifacts', 'transcript');
332	    mkdirSync(dir, { recursive: true });
333	    writeFileSync(join(dir, '.interrupted.tmp'), 'partial');
334	    const contents = ['', '世界 🧙\u0000\r\n'.repeat(200_000), 'other content'];
335	    const stored = await Promise.all(
336	      contents.flatMap((content) => [
337	        store.put('transcript', content),
338	        new FsArtifactStore(dataDir).put('transcript', content),
339	      ]),
340	    );
341	    for (const [i, content] of contents.entries()) {
342	      const a = stored[i * 2]!;
343	      expect(stored[i * 2 + 1]).toEqual(a);
344	      expect(a.bytes).toBe(Buffer.byteLength(content));
345	      expect(await store.get(a.ref)).toBe(content);
346	      expect(await store.get(a.ref.toUpperCase())).toBeUndefined();
347	      expect(readFileSync(join(dir, a.ref.split('/')[1]!)).equals(Buffer.from(content))).toBe(true);
348	    }
349	    expect(new Set(stored.map((item) => item.ref)).size).toBe(contents.length);
350	    expect(readdirSync(dir).sort()).toEqual(
351	      [
352	        '.interrupted.tmp',
353	        ...stored.filter((_, i) => i % 2 === 0).map((item) => item.ref.split('/')[1]!),
354	      ].sort(),
355	    );
356	  });
357	
358	  it('stores content once by hash and reads it back by reference', async () => {
359	    const store = new FsArtifactStore(dataDir);
360	    const first = await store.put('transcript', 'hello world');
361	    const second = await store.put('Transcript', 'hello world');
362	    expect(first.ref).toBe(second.ref);
363	    expect(first.ref).toMatch(/^artifact:transcript\/[a-f0-9]{64}$/);
364	    expect(first.bytes).toBe(11);
365	    expect(await store.get(first.ref)).toBe('hello world');
366	    const weird = await store.put('kind with spaces/and slashes', 'x');
367	    expect(weird.ref.startsWith('artifact:kind_with_spaces_and_slashes/')).toBe(true);
368	    const empty = await store.put('', 'y');
