378	  });
379	
380	  it('reports a typed publication failure without a final artifact when storage is unavailable', async () => {
381	    const store = new FsArtifactStore(dataDir);
382	    writeFileSync(join(dataDir, 'artifacts'), 'a file blocks the artifact directory');
383	    await expect(store.put('transcript', 'complete')).rejects.toMatchObject({
384	      code: 'ARTIFACT_WRITE_FAILED',
385	    });
386	  });
387	
388	  it('returns undefined for malformed or missing references', async () => {
389	    const store = new FsArtifactStore(dataDir);
390	    expect(await store.get('nope')).toBeUndefined();
391	    expect(await store.get('artifact:transcript/../../etc/passwd')).toBeUndefined();
392	    expect(await store.get(`artifact:transcript/${'a'.repeat(64)}`)).toBeUndefined();
393	  });
394	
395	  it('rethrows unexpected filesystem errors', async () => {
396	    const store = new FsArtifactStore(dataDir);
397	    const { ref } = await store.put('kind', 'content');
398	    const hash = ref.split('/')[1] as string;
399	    // Make the expected file path a directory so reading it fails with something other than ENOENT.
400	    rmSync(join(dataDir, 'artifacts', 'kind', hash));
401	    const { mkdirSync } = await import('node:fs');
402	    mkdirSync(join(dataDir, 'artifacts', 'kind', hash));
403	    await expect(store.get(ref)).rejects.toThrow();
404	  });
405	});
