22	  key: string;
23	  ownerRunId: string;
24	  kind: 'workspace' | 'artifact';
25	  path: string;
26	  identity: string;
27	  physicalPath?: string | null;
28	}
29	export interface ResourceRemovalPlan {
30	  target: string;
31	  entries: { rel: string; directory: boolean; identity: string; bytes: number }[];
32	}
33	export interface ResourceCleanupPort {
34	  exclusive<T>(operation: () => Promise<T>): Promise<T>;
35	  inspect(resource: OwnedRunResource): Promise<ResourceRemovalPlan | undefined>;
36	  stage(resource: OwnedRunResource, plan: ResourceRemovalPlan): Promise<boolean>;
37	  remove(
38	    resource: OwnedRunResource,
39	    plan: ResourceRemovalPlan,
40	    signal?: AbortSignal,
41	  ): Promise<{ removed: boolean; bytes: number }>;
42	}
43	/** A quarantined generation is separate from a later publication at its original key. */
44	export function originalResource(resource: OwnedRunResource): OwnedRunResource {
45	  if (!resource.key.startsWith('quarantine:')) return resource;
46	  const key = resource.key.slice(76);
47	  if (quarantinedKey({ ...resource, key }) !== resource.key)
48	    throw new Error('Invalid quarantine job');
49	  return { ...resource, key };
50	}
51	export function quarantinedKey(resource: OwnedRunResource): string {
52	  return (
