import { realpath, stat } from 'node:fs/promises';
import { basename, dirname, join, resolve, sep } from 'node:path';

/** Directory keys include their separator, so prefix ranges cannot confuse sibling names. */
export const directoryKey = (path: string): string => {
  const absolute = resolve(path);
  const value = process.platform === 'win32' ? absolute.toLowerCase() : absolute;
  return value.endsWith(sep) ? value : value + sep;
};

/** Native realpath resolves junctions/short names; missing suffixes inherit their physical ancestor. */
export async function physicalDirectory(path: string): Promise<string | null> {
  let ancestor = resolve(path);
  const missing: string[] = [];
  for (let depth = 0; depth < 64; depth++) {
    try {
      const actual = await realpath(ancestor);
      if (!(await stat(actual)).isDirectory()) return null;
      return directoryKey(join(actual, ...missing));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') return null;
      const parent = dirname(ancestor);
      if (parent === ancestor) return null;
      missing.unshift(basename(ancestor));
      ancestor = parent;
    }
  }
  return null;
}

import { createVitestConfig } from '@graphgoblin/tooling/vitest';

// libsql's native addon crashes or hangs on Windows when it is loaded only inside a worker thread
// and that thread exits, and the sqlite folder's tests load it, so this package must run in child
// processes, never `threads` or `vmThreads`. See docs/research/sqlite-libsql.md.
// Script tests spawn real processes and have timed out at 5 s under full-parallel load on the
// development machine, so this package allows 20 s per test and hook.
// Expose gc at worker startup so disposable SQLite tests can release native statements before
// removing their files on Windows, without changing V8 flags at runtime in a shared worker.
export default createVitestConfig({
  test: { pool: 'forks', execArgv: ['--expose-gc'], testTimeout: 20_000, hookTimeout: 20_000 },
});

